import re
import six
from taf.sbts.oam.coam.admin.exceptions import IncorrectParameterValue
from taf.rfrl.bts.devices.generic_bts import GenericBts, login_logout
from taf.rfrl.bts.helpers.singleton import Singleton


class GenericSync(GenericBts):
    """Sync keywords for eNB and gNB"""

    @login_logout
    def verify_bts_sync_status(self, bts_id=0, sync_source=None, timeout=60, du_id=0):
        """
        Check synchronization source and if it is working.

        :param bts_id:      BTS id - related to Test Line configuration.
        :type bts_id:       int
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :type du_id:       int
        :param sync_source: Type of synchronization source - related to Test Line configuration
                            e.g. "1pps/ToD from external GNSS receiver", "1pps/ToD from Sync Hub Master",
                            default set to "1pps/ToD from external GNSS receiver".
        :type sync_source:  str
        :param timeout:     Timeout for the operation
        :type timeout:      float
        :return:            None
        """
        if sync_source is None:
            sync_source = self.patterns.default_sync_source

        sync_info_output = self.admin.get_bts_sync_source_status(timeout,
                                                                 connection=self.rest_alias.format(bts_id, du_id))

        sync_source_expected_state = {
            "status": {"availability": "Available", "usability": "Usable"},
            "isActive": True,
            "syncInputType": sync_source,
            "syncMode": "PhaseSync"
        }
        sync_source_state = sync_info_output["syncSourceInfo"][0]
        self._compare_sync_status(sync_source_expected_state["status"], sync_source_state["status"])
        self._compare_parameter_value("isActive", sync_source_expected_state, sync_source_state)
        self._compare_parameter_value("syncInputType", sync_source_expected_state, sync_source_state)
        self._compare_parameter_value("syncMode", sync_source_expected_state, sync_info_output)

    def _compare_sync_status(self, expected_sync_status, sync_status):
        """
        Compares dictionaries with sync status (expected vs real status).

        :param expected_sync_status: dict, expected status of synchronization source.
        :param sync_status: dict, real status of synchronization source.
        """
        for sync_status_param in expected_sync_status:
            self._compare_parameter_value(sync_status_param, expected_sync_status, sync_status)

    @staticmethod
    def _compare_parameter_value(param_name, expected, source):
        """
        Compares single parameter value (expected vs real value).
        :param param_name: name of the value to compare.
        :param expected: dict, dictionary with expected parameters values.
        :param source: dict, dictionary with real parameters values.
        """
        if not re.match(str(expected[param_name]),
                        str(source[param_name]), re.I):
            raise IncorrectParameterValue(
                "'{}' should be {} but is {}".format(param_name, expected[param_name], source[param_name]))


@six.add_metaclass(Singleton)
class EnbSync(GenericSync):
    """Class contains Sync keywords for eNB"""

    bts_type = 'ENB'

    def __init__(self):
        """
        Constructor of Enb class.
        """

        super(EnbSync, self).__init__(bts_type=EnbSync.bts_type)


@six.add_metaclass(Singleton)
class GnbSync(GenericSync):
    """Class contains Sync keywords for gNB"""

    bts_type = 'GNB'

    def __init__(self):
        """
        Constructor of Gnb class.
        """
        super(GnbSync, self).__init__(bts_type=GnbSync.bts_type)
